const fs = require('fs'), path = require('path'), https = require('https'), http = require('http');
const DIR = '/tmp/persona';
const FILE = path.join(DIR, 'users.json');
const PENDING_FILE = path.join(DIR, 'pending.json');

function loadData() {
  if (!fs.existsSync(FILE)) return { users: {}, sessions: {} };
  try { return JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch(e) { return { users: {}, sessions: {} }; }
}

function fetchURL(url, redirects) {
  redirects = redirects === undefined ? 3 : redirects;
  return new Promise((resolve) => {
    const mod = url.startsWith('https') ? https : http;
    const req = mod.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Persona/1.0)' }, timeout: 8000 }, (res) => {
      if ((res.statusCode === 301 || res.statusCode === 302) && res.headers.location && redirects > 0) {
        return resolve(fetchURL(res.headers.location, redirects - 1));
      }
      let data = ''; res.on('data', c => data += c); res.on('end', () => resolve(data));
    });
    req.on('error', () => resolve('')); req.on('timeout', () => { req.destroy(); resolve(''); });
  });
}

function parseRSS(xml, max) {
  max = max || 8;
  const items = [], rx = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = rx.exec(xml)) !== null && items.length < max) {
    const s = m[1];
    const title = ((s.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/) || [])[1] || '').trim();
    const link = ((s.match(/<link>([^<]+)<\/link>/) || s.match(/<link[^>]+href="([^"]+)"/) || [])[1] || '').trim();
    const desc = ((s.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/) || [])[1] || '').replace(/<[^>]+>/g, '').trim().slice(0, 200);
    if (title && link) items.push({ title, link, description: desc });
  }
  return items;
}

const data = loadData();
const now = new Date();
const dayMap = ['sun','mon','tue','wed','thu','fri','sat'];
const curDay = dayMap[now.getDay()];
const curMin = now.getHours() * 60 + now.getMinutes();

let pending = [];
if (fs.existsSync(PENDING_FILE)) {
  try { pending = JSON.parse(fs.readFileSync(PENDING_FILE, 'utf8')); } catch(e) {}
  try { fs.writeFileSync(PENDING_FILE, '[]'); } catch(e) {}
}

const dueUsers = Object.entries(data.users).filter(([un, u]) => {
  if (!u.email || !u.topics || !u.topics.length) return false;
  if (pending.includes(un)) return true;
  if (!u.active || !u.schedule_time) return false;
  if (u.schedule_days && u.schedule_days.length && !u.schedule_days.includes(curDay)) return false;
  const [h, mi] = u.schedule_time.split(':').map(Number);
  if (Math.abs(curMin - (h * 60 + mi)) > 1) return false;
  if (u.last_newsletter && new Date(u.last_newsletter).toDateString() === now.toDateString()) return false;
  return true;
}).map(([un, u]) => ({ username: un, email: u.email, topics: u.topics, display_name: u.display_name || un, custom_prompt: u.custom_prompt || null }));

if (dueUsers.length === 0) return [];

const FEEDS = [
  { url: 'http://feeds.bbci.co.uk/news/rss.xml', category: 'General' },
  { url: 'http://feeds.bbci.co.uk/news/technology/rss.xml', category: 'Technology' },
  { url: 'http://feeds.bbci.co.uk/news/science_and_environment/rss.xml', category: 'Science' },
  { url: 'http://feeds.bbci.co.uk/news/business/rss.xml', category: 'Business' },
  { url: 'http://feeds.bbci.co.uk/news/health/rss.xml', category: 'Health' },
  { url: 'http://feeds.bbci.co.uk/news/world/rss.xml', category: 'World' },
  { url: 'https://techcrunch.com/feed/', category: 'Technology' },
  { url: 'http://feeds.bbci.co.uk/sport/rss.xml', category: 'Sports' },
  { url: 'http://feeds.bbci.co.uk/news/politics/rss.xml', category: 'Politics' },
  { url: 'http://feeds.bbci.co.uk/news/entertainment_and_arts/rss.xml', category: 'Entertainment' },
  { url: 'https://www.theguardian.com/environment/climate-crisis/rss', category: 'Climate' }
];

const seen = new Set(), allArticles = [];
for (const feed of FEEDS) {
  try {
    const xml = await fetchURL(feed.url);
    if (!xml) continue;
    for (const item of parseRSS(xml, 8)) {
      if (!seen.has(item.link)) { seen.add(item.link); allArticles.push({ ...item, category: feed.category }); }
    }
  } catch(e) {}
}

return dueUsers.map(user => ({ json: { ...user, articles: allArticles, fetched_at: now.toISOString() } }));

return $input.all().map(item => {
  const { username, email, topics, display_name, custom_prompt, articles } = item.json;

  const articlesText = (articles || []).map((a, i) =>
    (i+1) + '. [' + a.category + '] ' + a.title + '
   ' + a.description + '
   URL: ' + a.link
  ).join('

');

  const system_prompt = 'You are a professional newsletter editor for Persona. Write the newsletter directly in clean HTML (no markdown, no code blocks).
Use this structure: <h2> for title, <h3> for article headlines, <p> for paragraphs, <a href='URL'> for links, <hr> between sections, <strong> for emphasis.
Do NOT use **, *, ##, ---, or any markdown. Output only HTML fragment (no html/head/body tags).
Tone: professional but approachable. Select 5-8 most relevant articles. Be concise.' + (custom_prompt ? '
User preferences: ' + custom_prompt : '');

  const user_prompt = 'Write a newsletter for ' + display_name + ' interested in: ' + (topics || []).join(', ') + '.

Available articles (' + (articles || []).length + '):

' + articlesText + '

Select the most relevant and write the newsletter.';

  return { json: { username, email, topics, display_name, custom_prompt, system_prompt, user_prompt } };
});

const mistralItems = $input.all();
const userItems = $('Build Newsletter Prompt').all();
const dateStr = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

return mistralItems.map((response, i) => {
  const userData = (userItems[i] || userItems[0]).json;
  let newsletterText;
  try { newsletterText = response.json.choices[0].message.content; }
  catch(e) { newsletterText = 'Unable to generate newsletter. Please try again.'; }

  const topics = (userData.topics || []).join(', ');
  const css = 'body{font-family:Georgia,serif;max-width:680px;margin:0 auto;padding:24px;color:#222;line-height:1.6}h1{color:#1a1a2e;border-bottom:3px solid #2563eb;padding-bottom:10px}h2{color:#1a1a2e;font-size:20px;margin-top:28px}h3{color:#1e40af;font-size:16px;margin-top:20px;margin-bottom:6px}p{margin:8px 0;font-size:15px}a{color:#2563eb;text-decoration:none}hr{border:none;border-top:1px solid #e5e7eb;margin:20px 0}.footer{margin-top:36px;padding-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#9ca3af}.badge{background:#eff6ff;color:#1d4ed8;font-size:11px;padding:2px 8px;border-radius:12px}';
  const htmlBody = '<!DOCTYPE html><html><head><meta charset=\'UTF-8\'><style>' + css + '</style></head><body><h1>Persona Newsletter</h1><p style=\'color:#6b7280;font-size:13px\'>' + dateStr + '</p><p><span class=\'badge\'>' + topics + '</span></p>' + newsletterText + '<div class=\'footer\'><p>You received this because you subscribed to Persona.<br>Topics: ' + topics + ' | To unsubscribe or delete your data (GDPR), use the Persona chatbot.</p></div></body></html>';

  return {
    json: {
      to_email: userData.email,
      username: userData.username,
      display_name: userData.display_name,
      subject: 'Votre Newsletter Persona — ' + dateStr,
      body_text: newsletterText,
      body_html: htmlBody,
      sent_at: new Date().toISOString()
    }
  };
});

const fs = require('fs');
const FILE = '/tmp/persona/users.json';

// Read from Build Email Content since emailSend may not pass custom fields through
const items = $('Build Email Content').all();

for (const item of items) {
  const { username, sent_at } = item.json;
  if (username) {
    try {
      const data = JSON.parse(fs.readFileSync(FILE, 'utf8'));
      if (data.users[username]) {
        data.users[username].last_newsletter = sent_at;
        fs.writeFileSync(FILE, JSON.stringify(data, null, 2));
      }
    } catch(e) {}
  }
}

return items.map(item => ({ json: { success: true, username: item.json.username, to_email: item.json.to_email, sent_at: item.json.sent_at } }));
